const depth=document.querySelector('#depth-readout');const hudDepth=document.querySelector('#hud-depth');const stage=document.querySelector('#mask-stage');const model=document.querySelector('#mask-object');const heroImage=document.querySelector('.hero-image');const maskPng=document.querySelector('.mask-png');const heroModel=document.querySelector('#hero-model');const hologram=document.querySelector('.hologram');const heroCopy=document.querySelector('.hero-copy');const heroInfo=document.querySelector('.hero-info');const infoCards=[...document.querySelectorAll('.info-card')];const shotLabel=document.querySelector('.shot-label');const detail=document.querySelector('#node-detail');let drag=false,startX=0,startY=0,rx=-12,ry=-23;function render(){model.style.transform=`rotateX(${rx}deg) rotateY(${ry}deg)`}function clamp(v){return Math.max(0,Math.min(1,v))}function update(){const hero=clamp(window.scrollY/(window.innerHeight*3.95));const sceneIn=clamp(hero/.22);const infoIn=clamp((hero-.29)/.18);const jump=clamp((hero-.63)/.25);const modelIn=clamp((jump-.22)/.62);const p=Math.min(1,window.scrollY/(document.body.scrollHeight-innerHeight));heroImage.style.opacity=String(sceneIn*.84);heroImage.style.transform=`scale(${1+jump*.18})`;heroImage.style.filter=`saturate(${.55+sceneIn*.28}) contrast(${1.08+jump*.12})`;maskPng.style.opacity=String(sceneIn*(1-jump));maskPng.style.transform=`translate(${-jump*11}%,${jump*3}%) scale(${.88+sceneIn*.12+jump*1.75})`;maskPng.style.filter=`drop-shadow(0 26px 50px #000c) blur(${jump*6}px)`;heroModel.style.opacity=String(modelIn);heroModel.style.transform=`translateX(${(1-modelIn)*32}vw) scale(${.82+modelIn*.18})`;heroModel.setAttribute('camera-orbit',`${-10-modelIn*112}deg ${72+modelIn*16}deg ${3.2-modelIn*1.7}m`);heroModel.setAttribute('field-of-view',`${31-modelIn*9}deg`);hologram.style.opacity=String(Math.min(1,sceneIn*1.5)*(1-jump));hologram.style.transform=`scale(${1+jump*.9})`;heroCopy.style.opacity=String(1-infoIn);heroCopy.style.transform=`translateY(${-infoIn*20}px)`;heroInfo.style.opacity=String(infoIn*(1-jump));infoCards.forEach((card,i)=>{const side=i===1?-1:1;card.style.transform=`translate(${side*jump*(90+i*30)}px,${-jump*(80+i*25)}px) rotate(${side*jump*8}deg)`;card.style.filter=`blur(${jump*6}px)`});shotLabel.style.opacity=String(modelIn);shotLabel.style.transform=`translateY(${(1-modelIn)*15}px)`;depth.textContent=`${(p*38).toFixed(1)}m`;hudDepth.textContent=(28+p*8).toFixed(1)}window.addEventListener('scroll',update,{passive:true});update();stage.addEventListener('pointerdown',e=>{drag=true;startX=e.clientX;startY=e.clientY;stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointermove',e=>{if(!drag)return;ry+=((e.clientX-startX)/5);rx-=((e.clientY-startY)/5);startX=e.clientX;startY=e.clientY;render()});stage.addEventListener('pointerup',()=>drag=false);document.querySelectorAll('.node').forEach(n=>n.addEventListener('click',()=>{detail.innerHTML=`<span>${n.textContent.trim()}</span><h3>${n.dataset.title}</h3><p>${n.dataset.copy}</p>`;detail.style.opacity='1'}));document.querySelector('#sound').addEventListener('click',e=>{const on=e.currentTarget.getAttribute('aria-pressed')==='true';e.currentTarget.setAttribute('aria-pressed',String(!on));e.currentTarget.textContent=on?'Sound off':'Sound on'});
